use std::io;
use std::process::{Child, Command, Stdio};

pub fn browser(origin: &str, capability: &str) -> io::Result<()> {
    // This URL is generated by the local host, never taken from catalog metadata.
    if !origin.starts_with("http://127.0.0.1:") || capability.len() != 64 || !capability.bytes().all(|b|b.is_ascii_hexdigit()) {
        return Err(io::Error::other("INVALID_LOCAL_BROWSER_LAUNCH"));
    }
    let url = format!("{origin}/#capability={capability}");
    #[cfg(target_os = "windows")]
    let mut command = { let mut c = Command::new("rundll32.exe"); c.args(["url.dll,FileProtocolHandler", &url]); c };
    #[cfg(target_os = "macos")]
    let mut command = { let mut c = Command::new("/usr/bin/open"); c.arg(&url); c };
    #[cfg(not(any(target_os = "windows", target_os = "macos")))]
    let mut command = { let mut c = Command::new("xdg-open"); c.arg(&url); c };
    command.stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).spawn()?;
    Ok(())
}

pub fn fixture_command() -> io::Result<Command> {
    let mut command = Command::new(std::env::current_exe()?);
    command.arg("--fixture-child");
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    // The built-in fixture does not spawn descendants. General application tree ownership
    // must be qualified separately before app-launch authority is implemented on an OS.
    Ok(command)
}

pub fn owned_identity(child: &Child) -> serde_json::Value {
    serde_json::json!({"pid":child.id(),"native_handle_owned":true,
        "tree_launch_authority":false,"process_group":if cfg!(unix){Some(child.id())}else{None},
        "windows_job_qualification":"NOT_IMPLEMENTED; general application launch disabled"})
}
